"""Implementation of actions for the Login UI in the Monaco application"""
from .objects.monaco_core_objects import MonacoCoreObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MONACO_APP_NAME
from interops.libraries.squish_actions.exceptions import FailedToFindObject

@deco.set_separate_app_context(MONACO_APP_NAME)
def enter_username(username: str) -> None:
    """Locates the Username text box on the main dashboard > types in the given Username string.

    :param str username: Username to be entered into the Username textbox
    """
    CommonActions.type_in_textfield(MonacoCoreObjects.user_Validation_User_Name_Textbox, username)

@deco.set_separate_app_context(MONACO_APP_NAME)
def enter_password(password: str) -> None:
    """Locates the Password text box on the main dashboard > types in the given Password string.

    :param str password: Password to be entered into the Password textbox
    """
    CommonActions.type_in_textfield(MonacoCoreObjects.user_Validation_Password_Textbox, password)

@deco.set_separate_app_context(MONACO_APP_NAME)
def click_login_button() -> None:
    """Locates the Login Button on the main dashboard > clicks located object using the primary mouse button.
    """
    CommonActions.left_click_object(MonacoCoreObjects.user_Validation_OK_Button)

# This is currently not used in the Monaco login page object, but is left here for future use if needed. Also the tabBar_TabItem_Work_List object is not currently defined in the MonacoCoreObjects class, so this function will not work until that is added.
@deco.set_separate_app_context(MONACO_APP_NAME)
def confirm_sucessful_login(waitTimeout: int=10000) -> bool:
    """Waits for the main Mosaiq Tool bar to appear and Returns True if it successfully does.

    :return: True or False
    :rtype: bool
    """
    try:
        return True if CommonActions.find_object(MonacoCoreObjects.tabBar_TabItem_Work_List, waitTimeout) is not None else False
    except FailedToFindObject:
        return False